# create_default_configurations ----
## Setup ----
# Load or prepare any necessary data for testing
data("data_big")
data_age_length <- FIMSFrame(data_big)

## IO correctness ----
test_that("`create_default_configurations()` works with correct inputs", {
  expected_names <- c("model_family", "module_name", "fleet", "data")
  default_configurations <- create_default_configurations(data_age_length)

  #' @description Test that the function creates a configuration table with the expected column structure.
  expect_equal(
    object = colnames(default_configurations),
    expected = expected_names
  )

  expected_names_unnested <- c(
    "model_family", "module_name", "fleet", "module_type",
    "distribution_type", "distribution"
  )
  default_configurations_unnested <- default_configurations |>
    tidyr::unnest(cols = data)

  #' @description Test that the detailed configuration table has the correct column structure.
  expect_equal(
    object = colnames(default_configurations_unnested),
    expected = expected_names_unnested
  )

  #' @description Test that the generated configuration correctly identifies the model family as `catch_at_age`.
  expect_equal(
    object = unique(default_configurations_unnested[["model_family"]]),
    expected = "catch_at_age"
  )

  #' @description Test that the function produces a consistent output by comparing to a stored snapshot.
  expect_snapshot_file(
    save_csv(default_configurations_unnested),
    "default_configurations.csv",
    compare = compare_file_text
  )
})

## Edge handling ----
test_that("`create_default_configurations()` handles edge-case inputs", {
  default_configurations_unnested <- create_default_configurations(data_age_length) |>
    tidyr::unnest(cols = data)

  reordered_data <- data_big |>
    dplyr::arrange(dplyr::desc(.data$timing), .data$fleet, .data$type, .data$age, .data$length)
  reordered_frame <- FIMSFrame(reordered_data)
  reordered_configurations <- create_default_configurations(reordered_frame) |>
    tidyr::unnest(cols = data)

  #' @description Test that reordering input rows does not change the generated module configuration table.
  expect_equal(
    object = reordered_configurations,
    expected = default_configurations_unnested
  )

  mock_additional_fleet <- data_big |>
    dplyr::filter(
      .data$fleet == "fleet1",
      .data$type %in% c("landings", "age_comp", "length_comp")
    ) |>
    dplyr::mutate(fleet = "fleet_mock")

  mock_data <- dplyr::bind_rows(data_big, mock_additional_fleet)
  mock_frame <- FIMSFrame(mock_data)
  mock_configurations <- create_default_configurations(mock_frame) |>
    tidyr::unnest(cols = data)

  #' @description Test that adding a new fleet with supported data types adds fleet-specific data and selectivity modules.
  expect_true(
    any(
      mock_configurations[["module_name"]] == "Selectivity" &
        mock_configurations[["fleet"]] == "fleet_mock"
    )
  )

  #' @description Test that adding a new fleet with supported data types creates only the expected fleet-specific data module types.
  expect_setequal(
    object = mock_configurations |>
      dplyr::filter(.data$fleet == "fleet_mock", .data$module_name == "Data") |>
      dplyr::pull(.data$module_type),
    expected = c("Landings", "AgeComp", "LengthComp")
  )
})

## Error handling ----
# Please remove/comment out the test template below if there are no built-in errors/warnings.
test_that("`create_default_configurations()` returns correct error messages", {
  #' @description Test that the function aborts and provides a clear error message if the input data is in the wrong format.
  expect_error(
    create_default_configurations(data = data.frame(a = 1)),
    regexp = "`data` must be a"
  )

  #' @description Test that the function aborts and provides a clear error message if an invalid `model_family` is specified.
  expect_error(
    create_default_configurations(
      data = data_age_length,
      model_family = "invalid_family"
    )
  )
})
